-- D12(2026-09-19 立):automations 复用会话线程。
-- 给 user_automations 增加可选 conversation_id 列,绑定聊天会话
-- (chat_conversations.id);非空时自动化执行注入该会话近期消息上下文,
-- 并把产出落库到同一会话(线程接力)。
-- 注意:严禁改动 0067_system_admin.sql / 0071_restore_admin_immutability.sql。

ALTER TABLE user_automations ADD COLUMN conversation_id uuid;
